const FORMULAS = [
 {name:'Gordon growth model',formula:'P0 = D1 / (r − g)',topic:'Discounted Dividend Valuation',meaning:'Values a stable perpetual dividend stream. Use next-period dividend D1 and require r > g.',trap:'Using D0 or letting g equal/exceed r.'},
 {name:'Implied required return from Gordon model',formula:'r = (D1 / P0) + g',topic:'Discounted Dividend Valuation',meaning:'The forward dividend yield plus expected stable growth.',trap:'Calling dividend yield the total return.'},
 {name:'Sustainable growth rate',formula:'g = ROE × retention ratio',topic:'Discounted Dividend Valuation',meaning:'Growth that can be supported by retained earnings when ROE and leverage assumptions remain stable.',trap:'Using payout ratio instead of retention.'},
 {name:'FCFF from net income',formula:'FCFF = NI + NCC + Int(1 − T) − FCInv − WCInv',topic:'Free Cash Flow Valuation',meaning:'Adds non-cash charges and after-tax interest to net income, then subtracts reinvestment.',trap:'Using pre-tax interest in the net-income bridge.'},
 {name:'FCFE from FCFF',formula:'FCFE = FCFF − Int(1 − T) + net borrowing',topic:'Free Cash Flow Valuation',meaning:'Converts cash available to all capital providers into cash available to common equity.',trap:'Subtracting net borrowing when the firm is a net issuer of debt.'},
 {name:'Stable-growth terminal value',formula:'TVn = CF(n+1) / (discount rate − g)',topic:'Free Cash Flow Valuation',meaning:'Capitalizes next-period cash flow at the terminal date.',trap:'Using the wrong year’s cash flow or inconsistent discount rate.'},
 {name:'Justified leading P/E',formula:'P0 / E1 = payout ratio / (r − g)',topic:'Market-Based Valuation',meaning:'Links a stable leading earnings multiple to payout, required return, and growth.',trap:'Mixing trailing earnings with a leading-multiple formula.'},
 {name:'Stable-growth P/B',formula:'P0 / B0 = (ROE − g) / (r − g)',topic:'Market-Based Valuation',meaning:'Book value is more valuable when sustainable profitability supports future distributions and growth.',trap:'Applying the relationship when assumptions are inconsistent.'},
 {name:'Residual income',formula:'RI = NI − (r × beginning BVE)',topic:'Residual Income Valuation',meaning:'Earnings in excess of the required equity capital charge.',trap:'Subtracting the charge on ending book equity in the standard period formula.'},
 {name:'Residual-income equity value',formula:'V0 = B0 + PV(expected future residual income)',topic:'Residual Income Valuation',meaning:'Current book value plus the present value of expected future residual income.',trap:'Ignoring clean-surplus assumptions and accounting quality.'},
 {name:'Clean-surplus relationship',formula:'BVE(end) = BVE(begin) + NI − dividends',topic:'Residual Income Valuation',meaning:'A basic book-equity roll-forward through earnings and distributions.',trap:'Ignoring items that bypass net income but change equity.'},
 {name:'Normalized earnings',formula:'Maintainable earnings = reported earnings ± supported adjustments',topic:'Private Company Valuation',meaning:'Adjust reported results for supported one-off, owner-specific, and non-operating items.',trap:'Adding back expenses that will recur or are necessary for operations.'},
 {name:'FCFF enterprise value to equity value',formula:'Equity value = enterprise value + non-operating assets − debt-like claims',topic:'Valuation Applications',meaning:'Move from value of operating assets available to capital providers to value attributable to common equity.',trap:'Double-counting cash or omitting debt-like claims.'}
];

const FLASHCARDS = [
 {id:'f1',front:'Which dividend belongs in the Gordon growth numerator?',back:'The next expected dividend, D1 = D0 × (1 + g). D0 was just paid and belongs one period earlier.'},
 {id:'f2',front:'What discount rate goes with FCFF?',back:'WACC, because FCFF is available to debt and equity capital providers.'},
 {id:'f3',front:'What discount rate goes with FCFE?',back:'The required return on equity, because FCFE is cash flow available to common shareholders.'},
 {id:'f4',front:'How do you calculate residual income?',back:'Net income minus the required return on equity multiplied by beginning book value of equity.'},
 {id:'f5',front:'Payout ratio versus retention ratio?',back:'Retention ratio = 1 − payout ratio. Sustainable growth is commonly ROE × retention ratio under stable assumptions.'},
 {id:'f6',front:'Control discount versus marketability discount?',back:'Control concerns decision rights; marketability concerns the ability to sell the interest efficiently at a fair price.'},
 {id:'f7',front:'What makes a comparable multiple credible?',back:'Consistent numerator/denominator definitions and economically similar growth, profitability, risk, accounting, and capital intensity.'},
 {id:'f8',front:'What is the clean-surplus relationship?',back:'Ending book equity = beginning book equity + net income − dividends, in the basic form.'},
 {id:'f9',front:'Why is EBITDA not free cash flow?',back:'It excludes taxes, capital expenditure, and working-capital investment, among other cash requirements.'},
 {id:'f10',front:'What should be in a terminal-value numerator?',back:'The cash flow for the period immediately after the terminal valuation date.'}
];

