function esc(v) { return String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];}); }
function pct(n,d) { return d ? Math.round((n/d)*100) : 0; }
function uniqueAttempted(p) { return new Set(p.attempts.map(function(a){return a.qid;})).size; }
function uniqueCorrect(p) { const last={}; p.attempts.forEach(function(a){last[a.qid]=a.correct;}); return Object.values(last).filter(Boolean).length; }
function latestFor(p,qid) { for(let i=p.attempts.length-1;i>=0;i--) if(p.attempts[i].qid===qid) return p.attempts[i]; return null; }
function correctRate(p) { const last={}; p.attempts.forEach(function(a){last[a.qid]=a.correct;}); const vals=Object.values(last).filter(function(v){return v!==null&&v!==undefined;}); return pct(vals.filter(Boolean).length,vals.length); }
function studyMinutes(p) { return Math.round(p.studyLog.reduce(function(s,x){return s+(x.minutes||0);},0)); }
function completedModule(p,m) { const qs=questions().filter(function(q){return q.module===m.id;}); if(!qs.length)return 0; return pct(qs.filter(function(q){return !!latestFor(p,q.id);}).length,qs.length); }
function questionStatus(p,q) { const a=latestFor(p,q.id); return a ? (a.correct===null||a.correct===undefined?'review':a.correct?'correct':'incorrect') : 'unattempted'; }
function moduleAttemptCount(p,m) { return p.attempts.filter(function(a){return getQuestion(a.qid).module===m.id;}).length; }
function relativeDate(value) { if(!value)return 'Not yet'; const d=new Date(value); if(Number.isNaN(d.getTime()))return '—'; return d.toLocaleDateString(undefined,{month:'short',day:'numeric'}); }
function formatMin(n) { if(n<60)return n+' min'; return Math.floor(n/60)+'h '+(n%60)+'m'; }
function notify(message,error) {
  let old=document.querySelector('.toast'); if(old)old.remove();
  const node=document.createElement('div'); node.className='toast'; node.textContent=message; if(error)node.style.background='#48242b';
  document.body.appendChild(node); clearTimeout(toastTimer); toastTimer=setTimeout(function(){node.remove();},3500);
}
async function copyToClipboard(text) {
  const value=String(text==null?'':text);
  if(navigator.clipboard&&typeof navigator.clipboard.writeText==='function'){
    try { await navigator.clipboard.writeText(value); return true; } catch(e) { /* Fall back to the legacy selection API. */ }
  }
  const field=document.createElement('textarea');
  field.value=value;field.setAttribute('readonly','');field.style.position='fixed';field.style.opacity='0';field.style.pointerEvents='none';
  document.body.appendChild(field);field.select();field.setSelectionRange(0,field.value.length);
  let copied=false;
  try { copied=!!(document.execCommand&&document.execCommand('copy')); } catch(e) { copied=false; }
  field.remove();
  if(!copied)throw new Error('Clipboard access was denied. Select and copy the text manually.');
  return true;
}
